target.css:
:root {
  --ink: #18263b;
  --navy: #243a5e;
  --blue: #3674c8;
  --sky: #dcecff;
  --paper: #fffdf7;
  --line: #c9d6e5;
  --coral: #f0645a;
  --mint: #a9dec8;
  --muted: #66758a;
  --white: #ffffff;
}

* {
  box-sizing: border-box;
}

.broadcast-card {
  width: 500px;
  overflow: hidden;
  border: 1px solid var(--navy);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 54px;
  padding: 9px 16px;
  border-bottom: 1px solid var(--navy);
  background: var(--sky);
}

.station-mark {
  display: flex;
  align-items: center;
  gap: 9px;
}

.dial {
  display: grid;
  width: 36px;
  height: 36px;
  place-items: center;
  border-radius: 50%;
  background: var(--navy);
  color: var(--white);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: -0.5px;
}

.call-sign {
  color: var(--navy);
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 1.4px;
}

.live-chip {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 9px;
  border: 1px solid var(--coral);
  border-radius: 999px;
  background: var(--white);
  color: var(--coral);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1px;
}

.live-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--coral);
}

.program-grid {
  display: grid;
  grid-template-columns: 42% 58%;
  min-height: 166px;
}

.now-panel {
  padding: 16px;
  border-right: 1px solid var(--line);
  background: var(--paper);
}

.eyebrow {
  margin: 0 0 6px;
  color: var(--blue);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.9px;
}

h1 {
  margin: 0;
  color: var(--navy);
  font-size: 21px;
  line-height: 1;
  letter-spacing: -0.7px;
}

.host {
  margin: 5px 0 10px;
  color: var(--muted);
  font-size: 12px;
}

.clock {
  margin: 0;
  color: var(--ink);
  font-size: 25px;
  font-weight: 800;
  line-height: 1;
  letter-spacing: -1px;
}

.clock span {
  color: var(--blue);
  font-size: 10px;
  letter-spacing: 0;
}

.meta-list {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 9px;
  margin: 11px 0 0;
  padding: 0;
  color: var(--muted);
  font-size: 10px;
  list-style: none;
}

.meta-list li span {
  color: var(--blue);
  font-weight: 800;
}

.timeline {
  padding: 12px 14px 9px;
  background: var(--white);
}

.timeline-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  padding-bottom: 7px;
  border-bottom: 1px solid var(--line);
}

h2 {
  margin: 0;
  color: var(--navy);
  font-size: 13px;
  letter-spacing: -0.2px;
}

.timeline-header span {
  color: var(--muted);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.8px;
}

.set-list {
  margin: 0;
  padding: 0;
  list-style: none;
}

.set-list li {
  display: grid;
  grid-template-columns: 38px 1fr 29px;
  align-items: center;
  min-height: 36px;
  border-bottom: 1px solid var(--line);
}

.set-list li:last-child {
  border-bottom: 0;
}

.set-list time {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
}

.track {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.track strong {
  color: var(--ink);
  font-size: 11px;
  line-height: 1.1;
}

.track small {
  color: var(--muted);
  font-size: 9px;
}

.set-list b {
  justify-self: end;
  padding: 3px 4px;
  border-radius: 4px;
  background: var(--sky);
  color: var(--blue);
  font-size: 8px;
  letter-spacing: 0.4px;
}

.set-list .active-set b {
  background: var(--coral);
  color: var(--white);
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 45px;
  padding: 8px 16px;
  border-top: 1px solid var(--navy);
  background: var(--navy);
}

.signal {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--mint);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.bars {
  display: flex;
  align-items: end;
  gap: 2px;
  height: 12px;
}

.bars i {
  display: block;
  width: 3px;
  border-radius: 2px;
  background: var(--mint);
}

.bars i:nth-child(1) { height: 4px; }
.bars i:nth-child(2) { height: 7px; }
.bars i:nth-child(3) { height: 10px; }
.bars i:nth-child(4) { height: 12px; }

button {
  border: 0;
  background: transparent;
  color: var(--white);
  font-size: 11px;
  font-weight: 700;
}

button span {
  margin-left: 4px;
  color: var(--mint);
  font-size: 15px;
}

